            }

            let uniffiHandleSuccess = { @Sendable (returnValue: AuthSession) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeAuthSession_lower(returnValue),
                        callStatus: RustCallStatus()
